insert into public.lawyers (slug, name, initials, avatar_color, photo_url, headline_en, headline_ka, bio_en, bio_ka, city, languages, years_experience, verified, sort_order) values
  ('nino-beridze', 'Nino Beridze', 'NB', '#6b1423', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=400&h=500&fit=crop&crop=faces', 'Business & Corporate Lawyer', 'ბიზნესის და კორპორატიული სამართლის იურისტი', 'Nino has spent over a decade helping founders register companies, structure investments, and protect their brands across Georgia. She is known for explaining complex corporate matters in plain language.', 'ნინო ათ წელზე მეტია ეხმარება დამფუძნებლებს კომპანიების რეგისტრაციაში, ინვესტიციების სტრუქტურირებასა და ბრენდის დაცვაში საქართველოში. იგი ცნობილია რთული კორპორატიული საკითხების მარტივად ახსნით.', 'Tbilisi', array['Georgian', 'English', 'Russian']::text[], 11, true, 0),
  ('giorgi-abashidze', 'Giorgi Abashidze', 'GA', '#1c1210', 'https://images.unsplash.com/photo-1560250097-0b93528c311a?w=400&h=500&fit=crop&crop=faces', 'Family Law Attorney', 'საოჯახო სამართლის ადვოკატი', 'Giorgi guides families through divorce, custody, and inheritance matters with a calm, practical approach, focused on protecting his clients and their children.', 'გიორგი ოჯახებს უძღვება განქორწინების, მეურვეობისა და მემკვიდრეობის საკითხებში მშვიდი და პრაქტიკული მიდგომით, კლიენტებისა და მათი შვილების დაცვაზე ორიენტირებით.', 'Tbilisi', array['Georgian', 'English']::text[], 9, true, 1),
  ('ana-kapanadze', 'Ana Kapanadze', 'AK', '#8a6d3b', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?w=400&h=500&fit=crop&crop=faces', 'Immigration Lawyer', 'საიმიგრაციო იურისტი', 'Ana specializes in residence permits, visas, and citizenship applications for foreigners relocating to Georgia, with particular experience supporting remote workers and small business owners.', 'ანა სპეციალიზირებულია ბინადრობის ნებართვების, ვიზებისა და მოქალაქეობის განაცხადებში საქართველოში გადმოსახლებული უცხოელებისთვის, განსაკუთრებული გამოცდილებით დისტანციური მუშაკებისა და მცირე ბიზნესის მფლობელების მხარდაჭერაში.', 'Batumi', array['Georgian', 'English', 'Turkish']::text[], 7, true, 2),
  ('levan-tsereteli', 'Levan Tsereteli', 'LT', '#6b1423', 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=400&h=500&fit=crop&crop=faces', 'Real Estate Lawyer', 'უძრავი ქონების იურისტი', 'Levan reviews and negotiates property purchase agreements, leases, and landlord-tenant disputes, helping clients avoid costly mistakes before signing.', 'ლევანი ამოწმებს და აწარმოებს მოლაპარაკებებს უძრავი ქონების ნასყიდობის ხელშეკრულებებზე, იჯარებსა და მეიჯარე-მოიჯარეს შორის დავებზე, ეხმარება კლიენტებს თავიდან აიცილონ ძვირადღირებული შეცდომები ხელმოწერამდე.', 'Tbilisi', array['Georgian', 'English']::text[], 13, true, 3),
  ('mariam-chkheidze', 'Mariam Chkheidze', 'MC', '#1c1210', 'https://images.unsplash.com/photo-1594744803329-e58b31de8bf5?w=400&h=500&fit=crop&crop=faces', 'Contracts Attorney', 'სახელშეკრულებო სამართლის ადვოკატი', 'Mariam drafts and reviews employment, service, and partnership agreements for small businesses, making sure contracts are clear and enforceable for both sides.', 'მარიამი ადგენს და ამოწმებს შრომით, სამომსახურეო და პარტნიორულ ხელშეკრულებებს მცირე ბიზნესებისთვის და უზრუნველყოფს, რომ ხელშეკრულებები ორივე მხარისთვის იყოს ნათელი და აღსრულებადი.', 'Kutaisi', array['Georgian', 'English', 'Russian']::text[], 8, true, 4),
  ('david-lomidze', 'David Lomidze', 'DL', '#8a6d3b', 'https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?w=400&h=500&fit=crop&crop=faces', 'Tax & Finance Lawyer', 'საგადასახადო და საფინანსო იურისტი', 'David advises freelancers and small businesses on Georgia''s small business tax status, international taxation, and financial compliance.', 'დავითი კონსულტაციას უწევს ფრილანსერებსა და მცირე ბიზნესებს საქართველოს მცირე ბიზნესის საგადასახადო სტატუსზე, საერთაშორისო დაბეგვრასა და ფინანსურ შესაბამისობაზე.', 'Tbilisi', array['Georgian', 'English']::text[], 10, true, 5),
  ('ketevan-japaridze', 'Ketevan Japaridze', 'KJ', '#6b1423', 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=400&h=500&fit=crop&crop=faces', 'Criminal Defense Attorney', 'სისხლის სამართლის ადვოკატი', 'Ketevan defends clients at every stage of criminal proceedings, from initial questioning through trial, with a strong record in procedural defense.', 'ქეთევანი იცავს კლიენტებს სისხლის სამართლის პროცესის ყველა ეტაპზე, პირველადი დაკითხვიდან სასამართლო პროცესამდე, საპროცესო დაცვაში ძლიერი გამოცდილებით.', 'Tbilisi', array['Georgian', 'Russian']::text[], 15, true, 6),
  ('irakli-mchedlishvili', 'Irakli Mchedlishvili', 'IM', '#1c1210', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=400&h=500&fit=crop&crop=faces', 'Notary Services', 'სანოტარო მომსახურება', 'Irakli provides notarization and certified translation of documents for individuals and businesses, including documents used abroad.', 'ირაკლი უზრუნველყოფს დოკუმენტების ნოტარიულ დამოწმებასა და დამოწმებულ თარგმანს ფიზიკური და იურიდიული პირებისთვის, მათ შორის საზღვარგარეთ გამოსაყენებელი დოკუმენტებისთვის.', 'Batumi', array['Georgian', 'English', 'Turkish']::text[], 12, true, 7)
